# --- ТГК-1 пересчёт по ТЗ: теплоноситель ПГ 50 % с ингибиторами коррозии (6 металлов), 40 950 кг, доставка ≈924 тыс. (prices_A)
Q, NMC_NV, NMC_V, DEL = 40950, 15970500, 19484010, 924000
def tgk(buy_vat):  # закупка ₽/кг с НДС
    c_v = Q * buy_vat + DEL; c_nv = c_v / 1.22; bid = NMC_NV * .9
    return dict(usn=(bid - c_v) / bid, osno=(bid - c_nv) / bid, p_usn=bid - c_v, p_osno=bid - c_nv, usn20=(NMC_NV * .8 - c_v) / (NMC_NV * .8))
T_lo, T_mid, T_hi = tgk(200), tgk(160), tgk(130)

# группа, лот, №, подача, НМЦ, УСН −10 %, ОСНО −10 %, прибыль УСН −10 % (₽), основа, условие/вывод
